import re

def parse_duration(s: str) -> int:
    s_stripped = s.strip()
    if not s_stripped:
        raise ValueError
    parts = s_stripped.split()
    units_order = {'h': 0, 'm': 1, 's': 2}
    units_seen = set()
    prev_priority = -1
    total_seconds = 0
    for part in parts:
        if not re.fullmatch(r'\d+[hmsHMS]', part):
            raise ValueError
        unit_char = part[-1].lower()
        num_str = part[:-1]
        num = int(num_str)
        if unit_char in units_seen:
            raise ValueError
        units_seen.add(unit_char)
        current_priority = units_order[unit_char]
        if current_priority < prev_priority:
            raise ValueError
        prev_priority = current_priority
        if unit_char == 'h':
            total_seconds += num * 3600
        elif unit_char == 'm':
            total_seconds += num * 60
        else:
            total_seconds += num
    return total_seconds
