class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self._tokens = capacity
        self._last_refill_time = clock()

    def _refill(self):
        now = self.clock()
        if now > self._last_refill_time:
            delta = now - self._last_refill_time
            added_tokens = delta * self.refill_per_sec
            self._tokens = min(self.capacity, self._tokens + added_tokens)
            self._last_refill_time = now

    def allow(self, cost: float = 1) -> bool:
        self._refill()
        if self._tokens >= cost:
            self._tokens -= cost
            return True
        return False

    @property
    def tokens(self) -> float:
        self._refill()
        return self._tokens
